   [2]={next_id=3, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I can't help but miss that time. Back then, Foden City didn't rain much, and sunlight would pour into the courtyard outside the clinic during lunch, where I and the other children would share the food you brought us.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_804.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 0, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [3]={next_id=4, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I thought time would continue like that forever, but when you left us, my life came to a standstill. It wasn't until I got a job at Schultz that it started moving again… This is also the place you hated the most.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_804.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 0, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
