   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="This time, you'd lied to her—exploited the pure trust she had in you.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="From the moment the call started, you'd already pinpointed Alicia and Elsida's approximate location. With your memory, reuniting with them wouldn't have been difficult.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="But the sudden appearance of the Anchor Space? You knew exactly who was behind it. The Coordinators hadn't just forced Alicia to make a choice—they'd backed you into a corner too.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=-1, abreast_id={101}, pType =2, cg_type =10, dialog=1, msg="Grenache had told you: whether it was the authorities or the underground, Foden City despised Leistance and the Star Council they represented. Because Leistance disrupted the city's delicate balance of order and lawless absurdity—like the thriving Purify Tincture trade.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
