   [104]={next_id=105, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Their names weren't on the warrant. If you regrouped, the ones hunting you would target them too—exposing their ties to Leistance in the process.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [105]={next_id=106, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="But if you separated, without their help, you'd be hard-pressed to even make it back to Moonlight Kiss through the tightening net.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [106]={next_id=107, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Yet you had to choose separation. Even if entering the Anchor Point was its own kind of suicide, if it came down to it, you'd rather Alicia be remembered as Foden City's [hero] than branded a fugitive like you.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1508.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
